const $=s=>document.querySelector(s);let activeMethod=0;let notes=[];try{notes=JSON.parse(localStorage.getItem('kivilcim-notes')||'[]');if(!Array.isArray(notes))notes=[]}catch{}const methods=[{title:'Pekiştirmeli öğrenme',cat:'YAPAY ZEKÂ',icon:'⌁',desc:'Bir ajan, eylemlerinin sonuçlarından öğrenir. Enerjiyi şimdi kullanmak ile daha sonra saklamak arasındaki karar, bir ödül sinyaliyle şekillenir.',q:'Öğrenen strateji, aynı koşullardaki basit bir kuralı gerçekten geçiyor mu?',tags:['Ajan','Ödül','Karar'],x:400,y:210,color:'#c9f09f'},{title:'Zaman serisi tahmini',cat:'YAPAY ZEKÂ',icon:'∿',desc:'Geçmiş tüketim ve üretim örüntülerinden geleceğe yönelik tahmin üretilir. Tahmin doğruluğu kadar karar maliyetine etkisi de önemlidir.',q:'Daha düşük tahmin hatası, her zaman daha düşük enerji maliyeti mi getirir?',tags:['Tahmin','Belirsizlik'],x:230,y:100,color:'#c9f09f'},{title:'Model öngörülü kontrol',cat:'ENERJİ SİSTEMLERİ',icon:'⌘',desc:'Sistemin modeli ve gelecek tahminleriyle bir karar ufku optimize edilir. İlk karar uygulanır; yeni bilgi geldiğinde plan yeniden hesaplanır.',q:'Tahmin hatası büyüdüğünde plan ne kadar dayanıklı kalır?',tags:['MPC','Optimizasyon'],x:620,y:135,color:'#b5c7ff'},{title:'Batarya arbitrajı',cat:'ENERJİ SİSTEMLERİ',icon:'↯',desc:'Enerjiyi düşük maliyetli saatlerde saklayıp pahalı saatlerde kullanır. Fiyat farkı, enerji kaybını ve yıpranmayı karşılamalıdır.',q:'Fiyat farkı, verim kaybından ve batarya yıpranmasından daha mı büyük?',tags:['BESS','Enerji dengesi'],x:575,y:360,color:'#b5c7ff'},{title:'Kayıt doğrulama',cat:'DOĞRULAMA',icon:'◇',desc:'İmzalı kayıtlar ve blokzincir, işlemlerin izlenebilirliği için farklı tasarımlar sunar. Seçim, güven modeline ve yönetişim ihtiyacına bağlıdır.',q:'Birden çok güvensiz taraf var mı, yoksa imzalı bir veritabanı yeterli mi?',tags:['İzlenebilirlik','Güven'],x:180,y:305,color:'#e8bfa0'},{title:'Adil karşılaştırma',cat:'DOĞRULAMA',icon:'◎',desc:'Yöntemler aynı veri, aynı karar kısıtları ve aynı değerlendirme dönemi üzerinde ölçülür. Eğitim verisinin geleceği görmesine izin verilmez.',q:'Sonuç, görülmemiş tarihlerde ve farklı senaryolarda da tekrarlanıyor mu?',tags:['Veri sızıntısı','Temel yöntem'],x:370,y:405,color:'#e8bfa0'}];
function toast(s){$('#toast').textContent=s;$('#toast').style.opacity=1;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.opacity=0,2600)}function show(id){document.querySelectorAll('.view').forEach(v=>v.classList.toggle('hidden',v.id!==id));document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===id));$('#breadcrumb').textContent={atlas:'Keşif atlası',lab:'Deney laboratuvarı',notes:'Araştırma defteri',about:'Nasıl çalışır?'}[id];window.scrollTo({top:0,behavior:'smooth'});if(id==='notes')renderNotes()}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>show(b.dataset.view));$('#help').onclick=()=>show('about');$('#openLab').onclick=()=>show('lab');
function select(i){activeMethod=i;let m=methods[i];$('#methodTitle').textContent=m.title;$('#methodDesc').textContent=m.desc;$('#methodQuestion').textContent=m.q;$('#category').textContent=m.cat;$('#methodIcon').textContent=m.icon;$('#cardNum').textContent=`0${i+1} / 06`;$('#chips').replaceChildren(...m.tags.map(t=>{let s=document.createElement('span');s.textContent=t;return s}));document.querySelectorAll('.node circle').forEach((c,j)=>{c.setAttribute('r',j===i?25:15);c.setAttribute('fill',j===i?methods[j].color:'#1e261c')})}
const ns='http://www.w3.org/2000/svg';function svgEl(tag,attrs){let e=document.createElementNS(ns,tag);Object.entries(attrs).forEach(([k,v])=>e.setAttribute(k,v));return e}for(let i=0;i<75;i++){let a=i*2.3999;let b=(i*17%75)*2.3999;let x=400+Math.cos(a)*(210+i%5*19),y=240+Math.sin(a)*(135+i%7*7),xx=400+Math.cos(b)*260,yy=240+Math.sin(b)*170;$('#web').append(svgEl('path',{d:`M${x},${y} Q400,240 ${xx},${yy}`,stroke:'#71876a',opacity:'.16',fill:'none','stroke-width':'.65'}))}methods.forEach((m,i)=>{let g=svgEl('g',{class:'node',tabindex:'0',role:'button','aria-label':m.title});g.append(svgEl('circle',{cx:m.x,cy:m.y,r:15,stroke:m.color,'stroke-width':1.5,fill:'#1e261c'}));let t=svgEl('text',{x:m.x,y:m.y+43,fill:'#d9e2d0','text-anchor':'middle'});t.textContent=m.title;g.append(t);g.onclick=()=>select(i);g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select(i)}};$('#nodes').append(g)});select(0);
function persist(){try{localStorage.setItem('kivilcim-notes',JSON.stringify(notes));renderNotes();toast('Araştırma defterine kaydedildi')}catch{toast('Tarayıcı kaydı başarısız. Depolama iznini kontrol et.')}}function add(text,type){notes.unshift({id:Date.now()+'-'+Math.random(),text,type,date:new Date().toLocaleString('tr-TR')});persist()}$('#saveMethod').onclick=()=>{let m=methods[activeMethod];add(m.title+'\n'+m.desc+'\nAraştırma sorusu: '+m.q,'Yöntem')};$('#addNote').onclick=()=>{let t=$('#noteText').value.trim();if(!t)return toast('Önce araştırma sorunu yaz.');add(t,'Kişisel not');$('#noteText').value=''};function renderNotes(){$('#noteCount').textContent=notes.length;$('#noteList').replaceChildren();if(!notes.length){let p=document.createElement('p');p.className='subtitle';p.textContent='Defterin henüz boş. Haritadan bir yöntem veya laboratuvardan bir deney ekle.';$('#noteList').append(p)}notes.forEach(n=>{let d=document.createElement('article');d.className='notecard';let b=document.createElement('button');b.textContent='Sil ×';b.setAttribute('aria-label','Kaydı sil');b.onclick=()=>{notes=notes.filter(x=>x.id!==n.id);persist()};let s=document.createElement('small');s.textContent=n.type+' · '+n.date;let p=document.createElement('p');p.textContent=n.text;d.append(b,s,p);$('#noteList').append(d)})}renderNotes();
let latest;function simulate(cap,pv,peak,eff){let soc=0,base=0,bat=0,rows=[];const eta=Math.sqrt(eff/100);for(let h=0;h<24;h++){let load=.48+1.35*Math.exp(-(((h-8)/1.8)**2))+1.8*Math.exp(-(((h-19)/2.3)**2));let solar=pv*Math.max(0,Math.sin((h-6)/12*Math.PI));let tariff=h<6?.12:h>=17&&h<22?peak:.23;let net=load-solar,grid=Math.max(0,net),charged=0,discharged=0;const before=soc;if(net<0){charged=Math.min(-net,3,(cap-soc)/eta);soc+=charged*eta}if(h<6){let c=Math.max(0,Math.min(3-charged,(cap-soc)/eta));charged+=c;soc+=c*eta;grid+=c}if(h>=17&&h<22&&net>0){discharged=Math.min(net,3,soc*eta);soc-=discharged/eta;grid-=discharged}base+=Math.max(0,net)*tariff;bat+=grid*tariff;rows.push({h,load,solar,tariff,grid,soc,charged,discharged,before})}return{base,bat,rows,cap,pv,peak,eff}}
function update(){let cap=+$('#cap').value,pv=+$('#pv').value,peak=+$('#price').value,eff=+$('#eff').value;$('#capV').textContent=cap+' kWh';$('#pvV').textContent=pv+' kW';$('#priceV').textContent=peak.toFixed(2)+' €/kWh';$('#effV').textContent='%'+eff;latest=simulate(cap,pv,peak,eff);let diff=latest.base-latest.bat;let eur=n=>n.toLocaleString('tr-TR',{minimumFractionDigits:2,maximumFractionDigits:2})+' €';$('#baseCost').textContent=eur(latest.base);$('#batCost').textContent=eur(latest.bat);$('#saving').textContent=eur(diff);$('#savingPct').textContent=latest.base>0?'%'+(100*Math.abs(diff)/latest.base).toFixed(1)+' '+(diff>=0?'daha düşük':'daha yüksek'):'Karşılaştırma tabanı sıfır';$('#finding').textContent=cap===0?'Batarya kapasitesi sıfır: iki stratejinin maliyeti eşit. Kapasiteyi artırarak depolamanın etkisini gözlemle.':diff>0?`Bu koşullarda batarya, şebeke maliyetini ${eur(diff)} azaltıyor. Bu fark yatırım geri dönüşü değildir; yıpranma ve batarya bedeli modele dahil değil.`:`Bu koşullarda batarya maliyeti ${eur(-diff)} artırıyor veya değiştirmiyor. Düşük fiyat farkı, kayıplar ve kullanılmadan kalan şarj avantajı azaltabilir.`;drawChart()}
function drawChart(){let s=$('#chart');s.replaceChildren();const max=Math.max(4,...latest.rows.flatMap(r=>[r.load,r.solar,r.soc]));for(let i=0;i<5;i++){let y=240-i*50;s.append(svgEl('line',{x1:45,x2:730,y1:y,y2:y,stroke:'#333c2f','stroke-dasharray':'3 5'}));let t=svgEl('text',{x:32,y:y+4,fill:'#929d8a','font-size':10,'text-anchor':'end'});t.textContent=(max*i/4).toFixed(1);s.append(t)}for(let h=0;h<24;h+=4){let t=svgEl('text',{x:45+h/23*685,y:265,fill:'#929d8a','font-size':10});t.textContent=String(h).padStart(2,'0')+':00';s.append(t)}let label=svgEl('text',{x:45,y:20,fill:'#929d8a','font-size':10});label.textContent='Üretim / tüketim: kWh (1 saat) · Doluluk: kWh';s.append(label);[['solar','#c9f09f'],['load','#b5c7ff'],['soc','#e8bfa0']].forEach(([key,color])=>{let d=latest.rows.map((r,i)=>`${i?'L':'M'}${45+i/23*685},${240-r[key]/max*200}`).join(' ');s.append(svgEl('path',{d,fill:'none',stroke:color,'stroke-width':2.5,'stroke-linecap':'round','stroke-linejoin':'round'}))})}
['cap','pv','price','eff'].forEach(id=>$('#'+id).oninput=update);$('#saveRun').onclick=()=>add(`Batarya: ${latest.cap} kWh · Güneş: ${latest.pv} kW\nAkşam tarifesi: ${latest.peak} €/kWh · Verim: %${latest.eff}\nBataryasız: ${latest.base.toFixed(2)} € · Bataryalı: ${latest.bat.toFixed(2)} €\nFark: ${(latest.base-latest.bat).toFixed(2)} €\nSentetik 24 saatlik profil; yatırım ve yıpranma hariç.`,'Deney');$('#downloadCSV').onclick=()=>{let csv='saat,tuketim_kWh,gunes_kWh,tarife_EUR_kWh,sebeke_kWh,batarya_kWh,sarj_kWh,desarj_kWh\n'+latest.rows.map(r=>[r.h,...['load','solar','tariff','grid','soc','charged','discharged'].map(k=>r[k].toFixed(5))].join(',')).join('\n');let a=document.createElement('a'),u=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));a.href=u;a.download='kivilcim-deney.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{$('#cap').value=8;$('#pv').value=b.dataset.preset==='solar'?8:4;$('#price').value=.4;$('#eff').value=90;update();show('lab')});document.querySelector('[data-method]').onclick=()=>{select(5);$('.insight').scrollIntoView({behavior:'smooth',block:'center'})};update();
